create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'user' check(role in ('user','admin','editor','seo_manager','analyst')), created_at timestamptz not null default now());
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,parent_id uuid references categories(id),description text,is_indexable boolean not null default true,created_at timestamptz not null default now());
create table if not exists brands(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,created_at timestamptz not null default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,brand_id uuid references brands(id),category_id uuid references categories(id),description text,short_description text,images jsonb not null default '[]',sku text,gtin text,mpn text,specifications jsonb not null default '{}',rating numeric(3,2),review_count integer default 0,current_price numeric(12,2),lowest_price numeric(12,2),highest_price numeric(12,2),average_price numeric(12,2),price_change numeric(8,2),availability text,pros jsonb not null default '[]',cons jsonb not null default '[]',ai_score numeric(5,2),price_performance_score numeric(5,2),quality_score numeric(5,2),popularity_score numeric(5,2),value_score numeric(5,2),active boolean not null default true,last_updated timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists merchants(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,website text,logo_url text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists affiliate_networks(id uuid primary key default gen_random_uuid(),name text not null,tracking_url text,commission_rate numeric(8,3),cookie_duration integer,priority integer default 0,active boolean not null default true,notes text,created_at timestamptz not null default now());
create table if not exists merchant_offers(id uuid primary key default gen_random_uuid(),product_id uuid not null references products(id) on delete cascade,merchant_id uuid not null references merchants(id),affiliate_network_id uuid references affiliate_networks(id),affiliate_url text,price numeric(12,2) not null,shipping numeric(12,2),availability text,last_checked timestamptz,active boolean not null default true,unique(product_id,merchant_id));
create table if not exists price_history(id bigint generated always as identity primary key,product_id uuid not null references products(id) on delete cascade,price numeric(12,2) not null,captured_at timestamptz not null default now(),source text);create index if not exists price_history_product_time on price_history(product_id,captured_at desc);
create table if not exists affiliate_clicks(id uuid primary key default gen_random_uuid(),product_id uuid references products(id),merchant_id uuid references merchants(id),page_id uuid,page_path text,placement text,session_id text,referrer text,device text,country text,campaign text,affiliate_url text,created_at timestamptz not null default now());create index if not exists affiliate_clicks_created on affiliate_clicks(created_at desc);
create table if not exists price_alerts(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,product_id uuid references products(id) on delete cascade,target_price numeric(12,2) not null,active boolean not null default true,triggered_at timestamptz,created_at timestamptz not null default now());
create table if not exists favorites(user_id uuid references auth.users(id) on delete cascade,product_id uuid references products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table if not exists comparisons(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id) on delete cascade,slug text unique,created_at timestamptz not null default now());create table if not exists comparison_products(comparison_id uuid references comparisons(id) on delete cascade,product_id uuid references products(id) on delete cascade,position integer not null,primary key(comparison_id,product_id));
create table if not exists seo_pages(id uuid primary key default gen_random_uuid(),path text unique not null,page_type text not null,title text,description text,canonical text,robots text default 'index,follow',og_image text,target_keyword text,is_indexable boolean default true,content_id uuid,last_audited_at timestamptz);create table if not exists seo_keywords(id uuid primary key default gen_random_uuid(),keyword text not null,search_intent text,current_position numeric,impressions bigint,clicks bigint,ctr numeric,period_start date,period_end date,created_at timestamptz default now());create table if not exists seo_tasks(id uuid primary key default gen_random_uuid(),keyword_id uuid references seo_keywords(id),page_id uuid references seo_pages(id),task_type text,priority text,status text default 'suggested',recommendation text,created_at timestamptz default now());
create table if not exists content(id uuid primary key default gen_random_uuid(),slug text unique,title text,body text,content_type text,author_name text,last_updated timestamptz default now(),published boolean default false);create table if not exists content_versions(id uuid primary key default gen_random_uuid(),content_id uuid references content(id) on delete cascade,body text,created_at timestamptz default now());
create table if not exists analytics_events(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),event_name text not null,product_id uuid references products(id),page_path text,metadata jsonb default '{}',created_at timestamptz default now());create index if not exists analytics_events_time on analytics_events(created_at desc);
create table if not exists automation_rules(id uuid primary key default gen_random_uuid(),name text not null,trigger_config jsonb not null,action_config jsonb not null,risk_level text not null default 'review',active boolean default true);create table if not exists automation_runs(id uuid primary key default gen_random_uuid(),rule_id uuid references automation_rules(id),status text,details jsonb,started_at timestamptz default now(),finished_at timestamptz);
create table if not exists audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id),action text not null,entity_type text,entity_id text,details jsonb,created_at timestamptz default now());
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id),type text,title text,body text,read_at timestamptz,created_at timestamptz default now());
create table if not exists system_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer as $$ select exists(select 1 from profiles where id=auth.uid() and role in ('admin','super_admin')); $$;
alter table profiles enable row level security; alter table favorites enable row level security; alter table price_alerts enable row level security; alter table products enable row level security; alter table merchant_offers enable row level security;
create policy if not exists profiles_self on profiles for all using(id=auth.uid()) with check(id=auth.uid());
create policy if not exists products_public on products for select using(active=true); create policy if not exists offers_public on merchant_offers for select using(active=true); create policy if not exists favorites_self on favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid());create policy if not exists alerts_self on price_alerts for all using(user_id=auth.uid()) with check(user_id=auth.uid());
